insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Countermovement Jump', 'CMJ', 'jump', 'cm', true, false, 'Hands on hips, rapid dip and maximal vertical jump. Record jump height. Note the device used (e.g. force plate, contact mat, app) because methods are not interchangeable.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Squat Jump', 'SJ', 'jump', 'cm', true, false, 'Hold a static squat (~90° knee angle) for 2-3 s, then jump without countermovement. Hands on hips.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Single-Leg Countermovement Jump', 'SL CMJ', 'jump', 'cm', true, true, 'Countermovement jump on one leg, hands on hips. Test each side.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Drop Jump (RSI)', 'DJ RSI', 'jump', 'ratio', true, false, 'Drop from a standardised box height, minimise contact time and jump maximally. Record reactive strength index (jump height / contact time) and note the box height.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Drop Jump Height', 'DJ', 'jump', 'cm', true, false, 'Drop jump from a standardised box height; record jump height and note the box height.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Repeated Jump Test (10/5)', '10/5 RJT', 'jump', 'ratio', true, false, 'Continuous maximal hops; record the mean RSI of the best 5 of 10 jumps.', 1);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '5 m Sprint', '5 m', 'speed', 's', false, false, 'Sprint from a standardised start. Record start method (e.g. 0.5 m behind first gate) and timing system.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '10 m Sprint', '10 m', 'speed', 's', false, false, 'Sprint from a standardised start. Record start method and timing system.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '20 m Sprint', '20 m', 'speed', 's', false, false, 'Sprint from a standardised start. Record start method and timing system.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '30 m Sprint', '30 m', 'speed', 's', false, false, 'Sprint from a standardised start. Record start method and timing system.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Flying 10 m Sprint', 'Flying 10', 'speed', 's', false, false, 'Time a 10 m zone after a standardised build-up distance (record it).', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '505 Change of Direction', '505', 'cod', 's', false, true, 'Sprint 10 m to a line, then 5 m beyond, turn 180° and sprint back through the timing gate. Test both turning sides.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, '5-10-5 Shuttle (Pro Agility)', '5-10-5', 'cod', 's', false, false, 'Start in the middle, sprint 5 yd to one side, 10 yd to the other, and 5 yd back through the start.', 2);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Yo-Yo Intermittent Recovery Test Level 1', 'Yo-Yo IR1', 'endurance', 'm', true, false, 'Audio-paced 2 x 20 m shuttles with 10 s active recovery. Record total distance.', 1);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Yo-Yo Intermittent Recovery Test Level 2', 'Yo-Yo IR2', 'endurance', 'm', true, false, 'Higher starting speed version of the Yo-Yo IR test. Record total distance.', 1);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Estimated 1RM (repetition test)', 'e1RM', 'strength', 'kg', true, false, 'Record the load lifted for a submaximal repetition test; note the exercise and estimation equation in the method field.', 1);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Single-Leg Squat to Box (reps)', 'SL squat reps', 'strength', 'reps', true, true, 'Maximum controlled single-leg squats to a standardised box height. Test each side.', 1);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Weight-Bearing Lunge Test', 'WBLT', 'mobility', 'cm', true, true, 'Knee-to-wall lunge; record the maximum toe-to-wall distance with the heel down.', 3);
insert into public.test_definitions (owner_id, name, short_name, category, unit, higher_is_better, bilateral, protocol, default_trials) values (null, 'Isometric Mid-Thigh Pull', 'IMTP', 'strength', 'N', true, false, 'Requires a force plate. Record peak force and note the device and analysis settings.', 3);
